import{_ as a,o as t,c as s,ao as o}from"./chunks/framework.CjadT2vc.js";const r="/BVDOutbreakSize/previews/PR711/assets/zone_rt_map.4_xjoMVj.png",i="/BVDOutbreakSize/previews/PR711/assets/zone_forecast.gnuS2qtX.png",u=JSON.parse('{"title":"Spatial results","description":"","frontmatter":{},"headers":[],"relativePath":"spatial.md","filePath":"spatial.md","lastUpdated":null}'),n={name:"spatial.md"};function h(l,e,p,c,d,m){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="Spatial-results" tabindex="-1">Spatial results <a class="header-anchor" href="#Spatial-results" aria-label="Permalink to &quot;Spatial results {#Spatial-results}&quot;">​</a></h1><p>Where the outbreak sits, health zone by health zone. These estimates come from the same fits as the <a href="./summary">Summary</a> and the full <a href="./analysis">Analysis</a>, and refresh whenever the data updates. See the <a href="./analysis">Analysis</a> page for the methods behind the health-zone model.</p><h2 id="Health-zones" tabindex="-1">Health zones <a class="header-anchor" href="#Health-zones" aria-label="Permalink to &quot;Health zones {#Health-zones}&quot;">​</a></h2><p>Each patch&#39;s infections split across its health zones, conditional on the province model. The maps colour each affected zone by its reproduction number at the cut-off, the two bounds of the 90% interval on its forecast confirmed cases over the coming week, and its confirmed cases to date. A zone whose reproduction-number interval straddles one is washed towards white, and a zone with too few infections for an estimate is grey.</p><p><img src="'+r+'" alt=""></p><p>The one-week-ahead confirmed-case forecast for the fifteen zones with the largest forecasts, each the national forecast times the zone&#39;s projected share.</p><p><img src="'+i+'" alt=""></p><p>The zone ranking and the composition check are in the <a href="/BVDOutbreakSize/previews/PR711/analysis#Health-zone-estimates">health-zone estimates</a> of the analysis, and the validation against last week&#39;s observed split is in the <a href="/BVDOutbreakSize/previews/PR711/sensitivity#Forecast-by-health-zone">zone forecast validation</a> of the sensitivity page. The same estimates are on the interactive map below.</p><h2 id="Health-zone-map" tabindex="-1">Health-zone map <a class="header-anchor" href="#Health-zone-map" aria-label="Permalink to &quot;Health-zone map {#Health-zone-map}&quot;">​</a></h2><p>Each affected health zone coloured by its current reproduction number, with the seven-day confirmed-case forecast, the confirmed cases to date and the zone&#39;s share of its patch&#39;s infections available from the switcher. Hover over a zone for its estimate and 90% credible interval, click it for every number, or open the table view for a sortable list. The map needs a browser, so it appears only on the documentation site.</p><p><a href="zone_map/index.html" target="_blank" rel="noopener">Open the map in a new tab</a>.</p><iframe src="zone_map/index.html" title="Health-zone map" loading="lazy" style="width:100%;height:640px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);"></iframe><hr><p>For the full results, methods and code see the <a href="./analysis">Analysis</a> page and the <a href="https://github.com/epiforecasts/BVDOutbreakSize" target="_blank" rel="noreferrer">epiforecasts/BVDOutbreakSize</a> repository.</p>',14)])])}const z=a(n,[["render",h]]);export{u as __pageData,z as default};
